NAME = 'CroSaric: Hrvatska Biblija Ivana Šarića'
BOOK = 'Judith'

CHAPTERS = {
    1: {
        1: 'Bilo je to dvanaeste godine kraljevanja Nabukodonozora, kralja Asiraca, koji vladaše u velikom gradu Ninivi. U to je vrijeme Arfaksad vladao nad Medijcima u Ekbatani.',
        2: 'On sagradi naokolo Ekbatane zidove od tesana i četverouglasta kamena, široka tri lakta i dugačka šest lakata; podigao je bedeme sedamdeset lakata u visinu i pedeset lakata u širinu.',
        3: 'Do vrata gradskih podiže kule stotinu lakata visoke, s temeljima koji su bili šezdeset lakata široki.',
        4: 'Vrata koja bijaše napravio uzdizahu se sedamdeset lakata u visinu, a široka bijahu četrdeset lakata, kako bi mogla kroz njih izaći golema vojska s povorkom pješaka.',
        5: 'U to vrijeme kralj Nabukodonozor vojevaše s kraljem Arfaksadom u velikoj ravnici koja se proteže na području Ragaua.',
        6: 'Uza nj se svrstaše svi oni koji su obitavali u planinskim predjelima, svi oni koji su prebivali do obala Eufrata, Tigrisa i Hidaspa, a tako i stanovnici ravnice Arioha, kralja elimskoga: mnogo je dakle bilo ljudstva koje se poredalo u redove naroda keleudskog.',
        7: 'Nabukodonozor, kralj Asiraca, uputi poruku svim stanovnicima Perzije, svima onima koji življahu na zapadu, stanovnicima Cilicije, Damaska, Libanona i Antilibanona i svim stanovnicima morske obale,',
        8: 'narodima Karmela, Gileada, Gornje Galileje i prostrane ravnice Ezdrelona,',
        9: 'svima onima koji prebivahu u Samariji i njezinim gradovima, u Transjordaniji sve do Jeruzalema, Batane, Kelusa, Kadeša, Egipatske rijeke, Tafnesa, Ramsesa i po svemu području Gešema,',
        10: 'sve do onkraj Tanisa i Memfisa, najposlije svima stanovnicima Egipta sve do granice Etiopije.',
        11: 'Ali stanovnici svake od tih pokrajina narugaše se poruci Nabukodonozora, kralja Asiraca, i ne okupiše se oko njega da bi uza nj vojevali. Nisu ga se bojali, jer on za njih bijaše običan čovjek. Otposlaše praznih ruku glasnike njegove, ne iskazavši im počasti.',
        12: 'Tada se Nabukodonozor užasno razbjesni protiv svih tih područja i zakle se svojim prijestoljem i svojim kraljevstvom da će im se osvetiti i mačem opustošiti sve pokrajine Cilicije, Damaska, Sirije, uništiti sve stanovnike koji življahu na području Moaba, plemena Amona, čitave Judeje i sve žitelje Egipta sve do obaju mora.',
        13: 'Godine sedamnaeste stade sa svojom vojskom protiv kralja Arfaksada, potuče ga u borbi, rasprši mu svu vojsku, konjaništvo i kola,',
        14: 'zagospodari njegovim gradovima, doprije do Ekbatane, zauze kule, opljačka trgovišta, svede sjaj njegov na sprdnju.',
        15: 'Arfaksada uhvati u planinama Ragaua, dade ga izbosti sulicama i tako ga se riješi zauvijek.',
        16: 'Vrati se tada u Ninivu sa svom svojom vojskom i s golemim mnoštvom ratnika što im se bijahu pridružili. Tu se u miru i spokojstvu on i njegova vojska predadoše besposlici i uživanju stotinu i dvadeset dana.',
    },
    2: {
        1: 'Godine osamnaeste, prvoga mjeseca, dana dvadeset i drugoga, u kraljevskoj palači Nabukodonozora, kralja asirskoga, smisliše tajnu osnovu o izvršenju osvete nad svakom pokrajinom, kako on već bijaše kazao.',
        2: 'Sazva sve svoje pomoćnike i sve svoje dostojanstvenike i saopći im svoju tajnu osnovu i svojim usnama odluči potpuno uništenje onih pokrajina.',
        3: 'I bi odlučeno da se unište posvema svi oni koji se ne bijahu pokorili naredbi njegovih usta.',
        4: 'Zatim, kako završi vijećanje, Nabukodonozor, kralj Asiraca, dozva k sebi Holoferna, vrhovnog zapovjednika sve vojske, drugoga po redu iza sebe, i kaza mu:',
        5: '"Ovako govori veliki kralj, gospodar sve zemlje: otići ćeš od mene i povest ćeš sa sobom ljude svjesne svoje snage, otprilike stotinu i dvadeset tisuća pješaka i mnoštvo od dvanaest tisuća konja i konjanika.',
        6: 'Poći ćeš protiv sve zemlje na zapadu, jer se ne odazva nalogu mojih usta.',
        7: 'Naredit ćeš im da pripreme zemlju i vodu, jer ću u svome bijesu nasrnuti na njih. Prekrit ću svu zemlju nogama svojih vojnika i pustit ću da je temeljito opljačkaju.',
        8: 'Njihovi će ranjenici ispuniti doline; svaki potok i rijeka razlit će se nabujavši od njihovih mrtvih tijela.',
        9: 'Otjerat ću ih kao prognanike do nakraj svijeta.',
        10: 'Ti dakle kreni pa mi zauzmi sve njihovo područje. Ako ti se predaju, ti ćeš mi ih sačuvati za dan njihove kazne.',
        11: 'Neka tvoje oko ne zna milosti prema odmetnicima, nego kamo god dođeš, podvrgni ih smrti i pljački u svoj zemlji koja ti je povjerena.',
        12: 'Kazah i svojom ću rukom izvesti, kunem se životom i snagom svoga kraljevstva.',
        13: 'Ti nemoj prekršiti ni jedne od zapovijedi svoga gospodara, nego izvrši doslovce sve ono što sam ti naredio i nemoj oklijevati da to provedeš."',
        14: 'Holoferno ode od svoga gospodara i sakupi sve vrhovne zapovjednike, vojskovođe i časnike vojske asirske,',
        15: 'prebroja ljude koje izabra za bojni raspored kao što je naredio gospodar njegov: stotinu dvadeset tisuća ljudi i dvanaest tisuća strijelaca na konjima',
        16: 'i svrsta ih kako se svrstavaju bojni redovi velika mnoštva.',
        17: 'Uze silan broj deva, magaraca i mazgi za prijenos njihove opreme, a tako i velik broj ovaca, volova i koza njima za opskrbu',
        18: 'i za hranu svakog pojedinog vojnika te napokon golemu količinu zlata i srebra iz kraljeva dvora.',
        19: 'Krenu sa svom vojskom da bi kao prethodnica Nabukodonozorova prekrio sve lice zemlje na zapadu kolima, konjanicima i izabranim pješacima.',
        20: 'Silno, izmiješano mnoštvo, kao skakavci ili kopneni pijesak nebrojeni, iđaše za njim.',
        21: 'Krenuše iz Ninive i nakon tri dana hoda stigoše do ravnice Bektileta, pa se utaboriše za Bektiletom, blizu planine koja se nalazi nalijevo od Gornje Cilicije.',
        22: 'Holoferno pokrenu svu vojsku, pješake, konjanike i kola, pa se odande uputi prema planinskim predjelima.',
        23: 'Razori Fud i Lud, orobi sve Rasisove sinove i sinove Izmaelove koji borave sučelice pustinji, južno od zemlje heleonske.',
        24: 'Prijeđe Eufrat, prođe kroz Mezopotamiju, razori sve gradove koji se nalaze na uzvisinama uzduž potoka Abrona, da bi izbio na more.',
        25: 'Zauze područje Cilicije, isječe na komade sve one koji mu se opirahu i stiže do međa Jafata na jug, nasuprot Arabiji.',
        26: 'Opkoli sve sinove Madijanove, zapali im šatore, ugrabi stada.',
        27: 'Za žetve žita siđe u nizinu Damaska, zapali im sve njive, uništi im stada i stoku, opljačka im gradove, opustoši polja i oštricom mača pobi sve mlado.',
        28: 'Tada spopade strah i užas sve stanovnike obala Sidona i Tira, žitelje Sura i Okine i sve žitelje Jamnije. I građane koji su živjeli u Azotu i Askalonu zahvati silan strah pred njim.',
    },
    3: {
        1: 'Poslaše mu zbog toga glasnike s miroljubivim prijedlozima i poručiše:',
        2: '"Evo, mi podanici velikoga kralja Nabukodonozora padamo ničice preda te: učini s nama što ti se prohtije.',
        3: 'Evo ti naših kuća, našega kraja, žitnih polja, stada, stoke: svi torovi naših šatora ovise samo o jednom tvome migu; služi se svime kako ti se ushtije i kako ti se svidi.',
        4: 'Evo, i naši su gradovi sa svojim stanovnicima robovi tvoji, samo dođi i učini s njima što je dobro u očima tvojim."',
        5: 'Ljudi dođoše do Holoferna i saopćiše mu te poruke.',
        6: 'On siđe s vojskom prema obali, postavi upravitelje po utvrđenim gradovima te iz tih gradova unovači posebno izabrane ljude kao pomoćnu vojnicu.',
        7: 'Građani i sav okoliš dočekaše ga s vijencima, plesovima i bubnjevima.',
        8: 'Poruši on sve njihove uzvišice, sravni sa zemljom svete gajeve njihove: bilo mu je najvelikodušnije dopušteno da razruši sva domaća božanstva kako bi svi narodi častili samo Nabukodonozora i svi ga jezici i plemena zazivali kao Boga.',
        9: 'Stiže tako nasuprot Ezdrelonu u blizini Dotaina, a to je sučelice velikoj judejskoj ravni. Utabori se između Gebe i Skitopolisa i tu se zadrža cio mjesec dana da sakupi opskrbu za svoju vojsku.',
    },
    4: {
        1: 'Sinovi Izraelovi koji življahu u Judeji dočuše što je Holoferno, vrhovni zapovjednik Nabukodonozora, kralja Asiraca, učinio drugim narodima i kako je opljačkao i razorio hramove njihove;',
        2: 'obuze ih neiskaziv strah od toga čovjeka i počeše strepiti zbog Jeruzalema i zbog Hrama Gospoda, Boga svoga.',
        3: 'Bjehu se tek vratili iz sužanjstva, sav narod Judeje bio se sabrao tek nedavno, i predmeti, žrtvenik i Hram bili su posvećeni poslije obeščašćenja.',
        4: 'Odaslaše zbog toga glasnike na područje Samarije, u Konu, Betoron, Belmajin, Jerihon, u Hobu, u Esoru i u Salemsku dolinu.',
        5: 'Prije svega zaposjedoše sve vrhove najviših brda, opasaše zidovima sela koja su se nalazila ondje i nagomilaše hranu i opremu za vođenje rata, jer polja njihova bijahu istom požeta.',
        6: 'Tada Joakim, veliki svećenik, koji se tih dana nalazio u Jeruzalemu, napisa stanovnicima Betulije i Betomestaima, koji je smješten nasuprot Ezdrelonu na ulazu u ravan blizu Dotaina,',
        7: 'i naredi da se zaposjednu brdski prijelazi, jer je preko njih vodio put u Judeju. A bilo je lako spriječiti neprijateljski upad, jer je klanac bio tako uzak da su samo dva čovjeka mogla odjednom proći.',
        8: 'Sinovi Izraelovi učiniše kako im je naložio Joakim, veliki svećenik, i starješine narodne koje življahu u Jeruzalemu.',
        9: 'Svaki Izraelac žarko podiže glas k Bogu i svi se poniziše pred Bogom:',
        10: 'oni i žene njihove, i djeca, i životinje, i pridošlice, i plaćenici i robovi nošahu kostrijet oko bokova.',
        11: 'Svi Izraelci i žene i djeca što življahu u Jeruzalemu padoše ničice pred Hramom, posuše glavu pepelom i prostriješe kostrijet pred Gospoda:',
        12: 'opasaše vrećama i žrtvenik i zazivahu žarko Boga Izraelova u jedan glas, da ne preda njihovu djecu pokolju, njihove žene u ropstvo, njihove gradove i baštinu njihovu rušenju a svetišta njihova obeščašćenju, pogrdi i ruglu pogana.',
        13: 'Bog usliša glas njihov i smilova se nad nevoljom njihovom: sav je narod postio mnogo dana u svoj Judeji i u Jeruzalemu pred Svetištem Boga Svevladara.',
        14: 'Veliki svećenik Joakim, svećenici koji su stajali pred Gospodom i svi oni koji su mu služili, vezavši kostrijet oko bokova, prinosili su svakidašnje žrtve paljenice, zavjetnice i dragovoljne prinose puka;',
        15: 'posuvši pepelom mitre, podizahu iz sve snage glas Gospodu da bi milostivo pogledao dom Izraelov.',
    },
    5: {
        1: 'Izvijestiše Holoferna, vrhovnog zapovjednika vojske asirske, da su se sinovi Izraelovi spremili za rat, da su zatvorili brdske prijelaze, utvrdili sve vrhove najviših planina te postavili prepreke u predjelima što se nalaze u ravnici.',
        2: 'On se rasrdi strahovito, sazva sve glavare moapske, vojskovođe amonske, sve primorske namjesnike',
        3: 'pa im kaza: "Recite mi, sinovi kanaanski: kakav je to narod koji nastava brdovite predjele? Kakvi su mu gradovi u kojima živi? Kolika je vojska njegova? U čemu je snaga njegova i moć njegova? Tko je kralj koji nad njima vlada i zapovijeda im vojskom?',
        4: 'Zašto je među svima koji žive na zapadu on jedini gnjevno odbio da mi miroljubivo dođe u susret?"',
        5: 'Odgovori mu Ahior, vođa svih sinova Amonovih: "Poslušaj, moj gospodaru, riječi iz usta sluge svoga: ja ću te obavijestiti istinito o tome narodu koji, smješten blizu tebe, nastava taj brdovit kraj; neće izaći laž iz usta sluge tvoga.',
        6: 'Narod taj potječe od Kaldejaca.',
        7: 'Najprije su boravili u Mezopotamiji, jer su otklonili da se drže bogova otaca svojih koji su živjeli u zemlji kaldejskoj.',
        8: 'Skrenuše dakle s puta otaca svojih pa počeše štovati Boga nebeskoga, onoga Boga koga bijahu spoznali. I zato, udaljeni od lica svojih bogova, skloniše se u Mezopotamiju i tu se dugo zadržaše.',
        9: 'Pa im Bog njihov zapovjedi da ostave to prebivalište i odu u zemlju Kanaan; naseliše se ondje te imađahu u obilju zlata i srebra i mnogo stoke.',
        10: 'Spustiše se poslije u Egipat, jer glad bijaše pritisla zemlju kanaansku; ondje su ostali dok se imahu čime hraniti. Porastoše u snažno mnoštvo; rodu njihovu ne bijaše broja.',
        11: 'Ali se kralj Egipta diže na njih, naruga im se u pravljenju opeke; ponizi ih i učini robovima.',
        12: 'Onda oni zavapiše Bogu svome, a on svu zemlju egipatsku udari ranama bez prebola. Zbog toga ih Egipćani otjeraše od sebe.',
        13: 'Bog pred njima isuši Crveno more',
        14: 'i prevede ih preko Sinaja i Kadeš Barne. Oni odbiše od sebe sve nasrtaje stanovnika pustinje,',
        15: 'smjestiše se na području Amorejaca i vlastitom snagom istrijebiše sve Hešbonce. Prijeđoše preko Jordana i dobiše u nasljedstvo sav planinski kraj;',
        16: 'istjeraše Kanaanca, Perižanina, Jebusejca, Sihemca i sve Girgašane i tu obitavahu mnogo vremena.',
        17: 'Dok ne sagriješiše protiv Boga svoga, pratilo ih je blagostanje, jer je bio s njima Bog komu je mrska nepravda;',
        18: 'ali kad se udaljiše od puta što im ga on bijaše naznačio, u mnogim ratovima pretrpješe užasna razaranja, zatočiše ih u zemlju koja nije bila njihova. Hram Boga njihova bi razoren do temelja, a gradove im oteše neprijatelji njihovi.',
        19: 'Ali sada, kako su se vratili Bogu svome, uspeše se iz raznih krajeva kamo bijahu raspršeni i ponovo zauzeše Jeruzalem, gdje se nalazi Svetište njihovo, i smjestiše se po brdovitim krajevima koji bijahu opustjeli.',
        20: 'Zato, gospodaru, pomno izvidimo je li taj narod u čemu zastranio, je li sagriješio Bogu svome, pa ako utvrdimo da jest, onda možemo krenuti na nj i pokoriti ga;',
        21: 'ali ako narod onaj nije kriv ni zbog kakva prijestupa, onda neka gospodar moj odustane od nauma: jer će ih Bog njihov štititi, a mi ćemo biti na ruglo svoj zemlji."',
        22: 'Kada Ahior završi tu besjedu, stadoše rogoboriti oni koji su okruživali šator i nalazili se unaokolo, dostojanstvenici Holofernovi, svi stanovnici obalnih krajeva i Moaba: tražili su da ga raskomadaju:',
        23: '"Ne bojmo se sinova Izraelovih! To je zaista narod koji nema ni moći ni snage za žešću bitku.',
        24: 'Krenimo, dakle! Oni će biti samo zalogaj za vojsku tvoju, gospodaru Holoferno!"',
    },
    6: {
        1: 'Pošto je utihnula buka onih koji su se skupili na vijećanje, Holoferno, vrhovni zapovjednik asirske vojske, u nazočnosti svega naroda različita podrijetla i sviju sinova moapskih, obrati se Ahioru:',
        2: '"Tko si ti, Ahiore, ti i plaćenici Efrajimovi, da danas ovako prorokuješ među nama i savjetuješ da odustanemo od borbe protiv roda Izraelova? Bog njihov da bi im bio štit? Ali tko je Bog, osim Nabukodonozora? On će poslati svoju snagu i zbrisati ih s lica zemlje; ni Bog ih njihov neće spasiti.',
        3: 'Mi, sluge kraljeve, mi ćemo ih smrviti kao jednog čovjeka. Neće izdržati žestine našega konjaništva.',
        4: 'Njime ćemo ih zdrobiti. Brda će se natopiti njihovom krvlju, a ravnice se ispuniti njihovim mrtvim tijelima. Neće se ni održati pred nama, svi će izginuti. Tako govori kralj Nabukodonozor, gospodar sve zemlje. Tako je rekao, a riječi njegove neće ostati neispunjene.',
        5: 'A ti, Ahiore, plaćeniče amonski, koji si tako govorio u dan izopačenosti svoje, nećeš više gledati moga lica od današnjeg dana pa sve dok se ne osvetim rodu tih bjegunaca iz Egipta.',
        6: 'Tada će gvožđe mojih vojnika i sulica mojih slugu probosti slabine tvoje i ti ćeš pasti među ranjenike Izraela kad se ja okrenem protiv njega.',
        7: 'Za sada neka te sluge moje odvedu u brdoviti kraj i ostave u jednome od prilaznih gradova:',
        8: 'nećeš poginuti dok ne budeš zatrt s njima.',
        9: 'Ako u srcu svome gajiš nadu da neće biti osvojeni, zašto onda tvoje lice pokazuje toliku utučenost? Rekoh: nijedna od riječi mojih neće ostati neispunjena."',
        10: 'Holoferno potom naredi slugama koji bijahu u šatoru njegovu da zgrabe Ahiora, odvedu u Betuliju i predaju u ruke sinova Izraelovih.',
        11: 'Njegove ga sluge uhvatiše, odvedoše izvan tabora prema ravnici, iz ravnice provedoše ga prema brdima i dovedoše na izvore koji se nalaze pod Betulijom.',
        12: 'Kad su ih ljudi iz grada opazili, dohvatiše oružje, iziđoše iz grada prema vrhu brda, a praćari zauzeše put što se tuda uspinje i počeše bacati kamenice na njih da im spriječe penjanje.',
        13: 'Oni se onda skloniše pod brdo, svezaše Ahiora i ostaviše ga na podnožju brda, pa se vratiše svome gospodaru.',
        14: 'Sišavši iz svoga grada, sinovi Izraelovi priđoše mu, odvezaše ga i odvedoše u Betuliju i dovedoše pred gradske glavare.',
        15: 'Tih dana vršili su tu dužnost Ozija, sin Mihin od plemena Šimunova, pak Kabris, sin Gotonielov, i Harmis, sin Melkielov.',
        16: 'Dozvaše gradske starješine, ali dođoše na zbor i svi mladići i žene. Postaviše Ahiora usred svega naroda, a Ozija ga uzme ispitivati što to bijaše s njim.',
        17: 'Ahior ih izvijesti o svemu što je rečeno na Holofernovu vijećanju: što je sam kazao vođama Asurovim i što je u nadutosti svojoj Holoferno govorio protiv doma Izraelova.',
        18: 'Tada narod pade ničice, iskaza štovanje Bogu svome i zavapi:',
        19: '"Gospode, Bože nebeski, pogledaj oholost njihovu, budi milostiv poniznosti roda našega i obazri se danas na lica sebi posvećenih!"',
        20: 'Potom utješiše Ahiora i pohvališe ga.',
        21: 'Ozija ga sa zbora odvede u dom svoj i priredi starješinama gozbu. Svu noć dozivahu u pomoć Boga Izraelova.',
    },
    7: {
        1: 'Sutradan zapovjedi Holoferno svoj vojsci svojoj i svim narodima koji mu se bijahu pridružili u savezništvo da krenu na Betuliju, da zaposjednu putove što vode u brda i da zametnu rat protiv sinova Izraelovih.',
        2: 'Toga istog dana krenuše svi njihovi ratnici. Vojska se tih bojovnika sastojala od stotinu i sedamdeset tisuća pješaka i dvanaest tisuća konjanika, ne brojeći opremu i golemo mnoštvo ljudi koji su išli pješke među njima.',
        3: 'Utaboriše se u dolini nadomak Betuliji, uz izvor; zauzeše prostor u širinu od Dotaina do Belbaima, a u dužinu od Betulije do Kimona, koji se nalazi sučelice Ezdrelonu.',
        4: 'Kada sinovi Izraelovi vidješe sve to mnoštvo, u strahu počeše govoriti među sobom: "Ovi će potamaniti sve na zemlji! Ni najviše planine, ni klanci, ni bregovi neće izdržati pod njihovom težinom."',
        5: 'Svaki pograbi oružje; upalivši luči na svojim kulama, ostadoše na straži svu onu noć.',
        6: 'Ujutro izvede Holoferno sve konjaništvo pred oči sinova Izraelovih koji su se nalazili u Betuliji;',
        7: 'podvrže budnu nadzoru sve uspone koji su vodili do grada njihova, pretraži sve izvore vode i zauze ih i tu postavi vojničke straže pa se onda vrati k vojsci svojoj.',
        8: 'Dođoše k njemu svi poglavari sinova Ezavovih, sve vođe naroda moapskoga i vojskovođe obalnih krajeva te rekoše:',
        9: '"Neka posluša naš gospodar nekoliko naših riječi da ne bi pretrpio poraz vojske svoje.',
        10: 'Taj se narod sinova Izraelovih nije nikada uzdavao u svoja koplja nego u planinske uzvisine po kojima živi, jer nije se lako popeti na vrhove njihovih brda.',
        11: 'Zato se nemoj, gospodaru, boriti s njima kako se bori u otvorenoj bitki, pa neće poginuti ni jedan čovjek koji pripada tvome narodu.',
        12: 'Ostani u svome taboru čuvajući brižno svakoga svog vojnika. A dotle neka se tvoje sluge domognu vrela koje izvire na obronku.',
        13: 'Iz njega doista uzimaju vodu svi stanovnici Betulije. Žeđa će ih skončati i oni će predati grad. Mi ćemo se onda sa svojim četama popeti na obližnje gorske uzvisine pa na njima postaviti stražu da ni jedan čovjek ne izađe iz grada.',
        14: 'Glad će umoriti njih i njihove žene i njihovu djecu, pa još prije nego ih sasiječemo mačem, ležat će onemoćali po trgovima boravišta svoga.',
        15: 'Tada ćeš im groznom odmazdom platiti što se pobuniše i ne iziđoše ti s mirom u susret."',
        16: 'Razlaganje njihovo svidje se Holofernu i svim njegovim vojvodama. Izda on zapovijed da učine kako su ga svjetovali.',
        17: 'Krenu dakle odjel sinova Amonovih sa pet tisuća Asiraca pa se utabori u podolju, zauzevši nakapnice i izvore voda sinova Izraelovih.',
        18: 'Prema uzvisinama krenuše sinovi Ezavovi i sinovi Amonovi pa stadoše u brdovitu kraju nasuprot Dotainu, odakle poslaše jedan dio prema jugoistoku, sučelice Egrebelu, koji se nalazi blizu Kusa na obali potoka Mohmura. Ostali dio asirske vojske utabori se na ravnici pa prekri sve lice zemlje; šatori i silna oprema protezali im se u gustim nizovima tvoreći golemo mnoštvo.',
        19: 'Sinovi Izraelovi podigoše glas Gospodu Bogu svome, jer se obeshrabrio duh njihov zbog toga što bijahu opkoljeni od sviju neprijatelja svojih tako da im ne mogahu izmaći.',
        20: 'Trideset se i četiri dana nalazila oko njih asirska sila: pješaci, vojnička kola, konjanici. A onda stanovnicima Betulije nestade vode u sudovima,',
        21: 'a nakapnice im bijahu prazne; ni jedan dan nisu imali dovoljno pitke vode jer im se voda za piće davala na mjeru.',
        22: 'Djeca im bijahu iznemogla, žene im i mladići padali u nesvijest od žeđe: ležali su po gradskim trgovima ili u kućama, nisu više imali snage.',
        23: 'Tada sav narod, mladići, žene i djeca odoše k Oziji i gradskim upravljačima i povikaše i rekoše pred svim starješinama:',
        24: '"Neka Bog sudi između vas i nas zbog velike nepravde koju ste počinili na štetu našu jer niste htjeli mirno pregovarati s Asircima.',
        25: 'Sad nam nema više pomoći niodakle: Bog nas je predao u njihove ruke da iznemognemo od žeđe i posvemašnje iscrpljenosti.',
        26: 'A sada ih pozovite i predajte sav grad pljački Holofernovih ljudi i sve vojske njegove.',
        27: 'Jer nam je bolje da postanemo njihov plijen. Bit ćemo, doduše, njihovi robovi, ali ćemo sačuvati živote i nećemo rođenim očima gledati smrt djece svoje niti kako nam žene i djeca ispuštaju dušu.',
        28: 'U ime neba i zemlje, u ime Boga i Gospoda otaca naših, koji nas je kaznio zbog grijeha naših i poradi prijestupa otaca naših, zaklinjemo vas da još danas izvršite što smo vam kazali."',
        29: 'Usred zbora nasta sveopći plač i svi glasno zavapiše Gospodu Bogu.',
        30: 'Ozija im upravi riječ: "Budite hrabri, braćo, ustrajmo još pet dana, za kojih će Gospod Bog naš izliti na nas milost svoju: zacijelo nas neće napustiti zauvijek.',
        31: 'Prođe li tih pet dana bez ikakve pomoći, izvršit ću što tražite."',
        32: 'Potom otpusti narod, svakoga u njegovu četvrt. Ljudi odoše na zidove i kule svoga grada, a žene i djecu poslaše njihovim kućama. Ali u gradu bijahu krajnje potišteni.',
    },
    8: {
        1: 'Tih dana sve je to čula Judita, kći Merarija, sina Oksa, sina Oziela, sina Elkija, sina Ananije, sina Gedeona, sina Rafaina, sina Ahitoba, sina Elije, sina Helkije, sina Eliaba, sina Natanaela, sina Salamiela, sina Sarasadaja, sina Izraelova.',
        2: 'Njezin muž Manaše, iz istoga plemena i obitelji, bješe umro za žetve ječma.',
        3: 'Nadgledavao je one koji su povezivali snopove na njivi kad ga pogodi sunčanica: pade na postelju i umrije u Betuliji, gradu svome; pokopaše ga do njegovih otaca u polju što se nalazi na pola puta između Dotaina i Balamona.',
        4: 'Judita odonda življaše kao udovica već tri godine i četiri mjeseca.',
        5: 'Načinila je sebi sobu na ravnome kućnom krovu, navukla preko bokova kostrijet i nosila haljine udovičke.',
        6: 'Postila je sve dane udovištva svoga, osim uoči subote i za samih subota, uoči mlađaka i za samih mlađaka te za svetkovina i blagdana doma Izraelova.',
        7: 'Bila je lijepa i naočita. Njezin muž Manaše bijaše joj ostavio zlata i srebra, slugu i sluškinja, stoke i zemljišta, i tako je živjela.',
        8: 'Ne bijaše nikoga koji bi kazao što ružno o njoj, jer je bila jako bogobojazna.',
        9: 'Dočula je dakle krute riječi koje puk, zapavši u malodušje zato što je nestalo vode, bijaše upravio gradskom starješini, a doznala je i sve što je Ozija rekao narodu i kako im se zakleo da će do pet dana predati grad Asircima.',
        10: 'Posla tada sluškinju koja je vodila njezine poslove da dozove gradske starješine Habrisa i Harmisa.',
        11: 'Dođoše oni k njoj, a ona im kaza: "Poslušajte me, glavari Betulije! Nije baš valjan govor što ste ga održali puku. A umetnuli ste u taj govor i zakletvu između Boga i vas i rekli da ćete predati grad neprijatelju ako vam Gospod u određenom roku ne pomogne.',
        12: 'A tko ste vi da danas iskušavate Boga i postavljate se iznad Boga među ljudima?',
        13: 'Ispitujte namisli Boga Svevladara koliko vam drago, pa svejednako nećete razumjeti ništa dovijeka.',
        14: 'Ako ne uspijevate istražiti dubine ljudskoga srce niti doznati ono što prolazi ljudskom mišlju, kako ćete dokučiti Boga koji je stvorio sve to? Kako ćete istražiti misao njegovu i shvatiti nakane njegove? Ne, braćo, nemojte ljutiti Gospoda Boga našega!',
        15: 'Jer ako nam i ne htjedne priskočiti u pomoć u ovih pet dana, ipak nas može zaštititi ali i zatrti, i to naočigled neprijatelja naših, u one dane kad mu se svidi.',
        16: 'Prema tome, ne tražite odluke Gospoda Boga našega, jer Bog nije čovjek da biste mu mogli prijetiti niti sin čovječji komu biste mogli naređivati.',
        17: 'Zbog toga, očekujući spas koji može doći od njega, dozivajmo ga u pomoć, i on će poslušati glas naš, bude li mu to drago.',
        18: 'Jer u našim pokoljenjima nije bilo, a nema ni dan-danas u našemu plemenu, obitelji, selu ili gradu onih koji bi štovali boštva načinjena rukama, kao što je bivalo u prijašnja vremena.',
        19: 'Zato su očevi naši bili predani maču, bili su pljačkani i doživjeli velike poraze od neprijatelja.',
        20: 'Ali mi ne znamo drugoga Boga do njega, pa se stoga nadamo da neće napustiti ni nas ni ikoga od našeg plemena.',
        21: 'Jer budemo li osvojeni mi, bit će osvojena i sva Judeja i opljačkano naše Svetište, a on će to obeščašćenje osvetiti našom krvlju.',
        22: 'Pokolj braće naše, tjeranje svega naroda u progonstvo i opustošenje baštine naše oborit će na glavu našu među poganima među kojima ćemo se nalaziti kao robovi i biti predmet pogrde i ismjehivanja za naše gospodare,',
        23: 'jer se naše ropstvo neće pretvoriti u naklonost nego će ga Gospod Bog naš pretvoriti u porugu.',
        24: 'Stoga, braćo, pokažimo svojoj braći da od nas zavisi život njihov te da Svetište, Hram i žrtvenik počivaju na nama.',
        25: 'Zbog svega toga zahvalimo radije Gospodu Bogu našemu što nas iskušava kao što je iskušavao i očeve naše.',
        26: 'Sjetite se kako je činio s Abrahamom, kako je iskušavao Izaka, što se dogodilo Jakovu u Mezopotamiji sirijskoj kad je pasao ovce Labana, svoga ujaka.',
        27: 'Jer kako je iskušavao njih da bi iskušao njihova srca, tako postupa s nama da se popravimo, a ne da nam se osveti, jer Bog iskušava one koji su mu blizu."',
        28: 'Ozija joj odgovori: "Sve što si izrekla iznosila si iz plemenitog srca i nitko se neće usprotiviti tvojim riječima.',
        29: 'Jer tvoja se mudrost ne očitova tek danas: još od početka tvojih dana sav je narod znao za tvoju umnost, za plemenitost srca tvoga!',
        30: 'Ali puk trpi užasno od žeđe, pa nas je prisilio da izvršimo ono što smo obećali i da se zakunemo zakletvom koje nećemo prekršiti.',
        31: 'Sada, budući da si ti pobožna žena, moli se za nas, a Gospod će poslati kišu i napuniti naše čatrnje da ne izginemo."',
        32: 'Odgovori im Judita: "Poslušajte me! Izvest ću djelo o kojemu će spomen prelaziti od pokoljenja na pokoljenje među sinovima našeg naroda.',
        33: 'Budite noćas na gradskim vratima da mognem izići sa svojom sluškinjom. Prije onog dana u koji ste namislili predati grad neprijateljima Gospod će rukom mojom donijeti spas Izraelu.',
        34: 'Ne tražite da vam kažem što sam namjerila. Neću vam odati ništa dok ne bude izvršeno ono što sam odlučila učiniti."',
        35: 'Ozija i prvaci rekoše joj: "Idi u miru! Neka Gospod Bog bude uza te da se uzmogneš osvetiti neprijateljima našim!"',
        36: 'Izišavši odande, vratiše se na svoja mjesta.',
    },
    9: {
        1: 'Tada Judita pade ničice, posu glavu pepelom i razotkri kostrijet koju je nosila na sebi. I upravo kad su u Jeruzalemu, u Domu Božjem, prinosili večernji tamjan, ona glasno zavapi Gospodu i reče:',
        2: '"O Gospode, Bože oca moga Šimuna, komu si ruku naoružao mačem da se osveti tuđincima koji bijahu radi sramote odriješili pas jedne djevice, obnažili njezin bok da je okaljaju i obeščastili njezinu utrobu za sramotu. Iako si kazao: \'Ne smije tako biti\', oni su svejedno učinili.',
        3: 'I zato si predao pokolju vođe njihove i krvi postelju njihovu, prevarenu i postiđenu njihovom prijevarom. Udario si po robovima i gospodarima; po vladarima na prijestoljima njihovim.',
        4: 'Predao si žene njihove plijenu, a kćeri njihove, svu imovinu njihovu odredio da bude razdijeljena među tvoje ljubljene sinove koji su gorjeli od revnosti prema tebi, užasavali se nad obeščašćenjem svoje krvi i zvali te u pomoć. O Bože, moj Bože, poslušaj i mene udovicu.',
        5: 'Ti si sazdao i ono što je bilo prije i što će biti poslije. Ti si zamislio i sadašnjost i budućnost i sve se dogodilo što si umom zasnovao.',
        6: "Što si nakanio, došlo je preda te i reklo: 'Evo me!' Jer svi su tvoji putovi pripremljeni, a tvoje odluke predviđene.",
        7: 'Eto, Asirci se uznose svojom vojskom, ponositi su na konje i konjanike svoje, oholi su zbog vrsnoće pješaka svojih, uzdaju se u štit, koplje, luk, praćku i neće da u tebi spoznaju Gospoda koji mrvi ratove.',
        8: 'Gospod je tvoje ime. Ti im skrši snagu moći svojom, savij silu gnjevom svojim. Jer su naumili da obeščaste tvoje Svetište, da okaljaju Šator gdje boravi preslavno Ime tvoje, da željezom raznesu uglove žrtvenika tvoga.',
        9: 'Vidi njihovu nadutost i upravi gnjev svoj na glave njihove, a moju udovičku ruku ojačaj za naumljeno djelo.',
        10: 'Pogodi zamamnošću mojih usana roba s vođom, a vođu s njegovim slugom. Razori drzovitost njihovu rukom jedne žene.',
        11: 'Tvoja snaga nije u mnoštvu niti moć tvoja u silnicima, nego si ti Bog poniznih, pomoćnik si malenih, potporanj slabih, utočište napuštenih, spasitelj očajnih.',
        12: 'Doista, Bože oca moga, Bože baštine Izraelove, gospodaru neba i zemlje, tvorče voda, kralju svega stvorenja, uslišaj molitvu moju!',
        13: 'Daj mi zamamnu riječ koja ranjava i obara u krvi one koji su strahote smislili protiv tvoga Saveza, svetog Doma, brda Siona i kuće sinova tvojih.',
        14: 'Učini da spozna sav narod tvoj i svako pleme da si ti Bog, Bog svake moći i snage, i da osim tebe nema drugoga zaštitnika rodu Izraelovu!"',
    },
    10: {
        1: 'Kad je prestala vapiti Bogu Izraelovu i kad je završila svoju molitvu,',
        2: 'ustade gdje bijaše pala ničice, dozva svoju sluškinju i siđe u odaje u kojima je provodila subote i svetkovine svoje.',
        3: 'Svuče sa sebe kostrijet, skide udovičke haljine, opra vodom tijelo, namaza se mirisavom mašću, počešlja kosu i stavi prevjes na glavu, odjenu se u svečane haljine u koje se odijevala dok je još živio muž njezin Manaše.',
        4: 'Obu sandale, metnu narukvice, ogrlice, prstenje, naušnice i sav nakit: uresi se što je mogla ljepše da bi očarala oči ljudi koji je budu gledali.',
        5: 'Sluškinji preda mijeh vina i vrč ulja, napuni dvojače ječmenom kašom, pogačama suhoga voća i čistim hljebovima; sve to složi i stavi na nju.',
        6: 'Uputiše se njih dvije prema vratima grada Betulije i tu nađoše Oziju s gradskim starješinama Habrisom i Harmisom.',
        7: 'Kad ovi ugledaše Juditu preobražena lica i u onome ruhu, zadiviše se ljepoti njezinoj pa će joj:',
        8: '"Bog otaca naših udijelio ti milost i dao ti da uspješno izvedeš što si naumila na slavu sinova Izraelovih i uzvišenje Jeruzalema."',
        9: 'Judita se pokloni Bogu, a njima reče: "Zapovjedite da mi otvore gradska vrata. Izići ću i izvesti što ste kazali." Oni narediše straži da otvori vrata kako je zatražila.',
        10: 'Otvoriše joj, pa Judita iziđe sa sluškinjom. Ljudi su je iz grada pratili pogledom dok se spuštala brdom i dok je poprijeko prelazila podoljem. Onda je više nisu vidjeli.',
        11: 'Dok su išle ravno podoljem, sretoše je asirske predstraže.',
        12: 'Zaustaviše je i upitaše: "Kojemu narodu pripadaš? Odakle dolaziš i kamo ideš?" Ona odgovori: "Kći sam Hebrejaca i bježim od njih, jer će vam se uskoro predati da vam budu hrana.',
        13: 'Zaputila sam se Holofernu, vrhovnom zapovjedniku vaše vojske, da se s njim iskreno porazgovorim. Pokazat ću mu put kojim će morati poći da bi zagospodario svim brdovitim krajem a da ne izgubi ni jednog čovjeka, ni jedne žive duše."',
        14: 'Dok su ti ljudi slušali riječi njezine i promatrali je, bijahu zadivljeni njezinom ljepotom. Rekoše joj:',
        15: '"Spasila si svoj život požurivši se da siđeš k našem gospodaru. Sada idi njegovu šatoru: nas nekolicina pratit ćemo te dok te ne predamo u ruke njegove.',
        16: 'Kada se budeš našla pred njim, ne drhti u srcu svome nego mu reci ono što si kazala i on će s tobom postupati dobro."',
        17: 'Izabraše između sebe stotinu ljudi. Oni su bili pratnja njoj i sluškinji njezinoj, pa ih dovedoše do Holofernova šatora.',
        18: 'U taboru se sve uskomešalo: vijest o Juditinu dolasku pođe od usta do usta po svim šatorima. Dođoše ljudi i poredaše se do nje dok je ona stajala pred Holofernovim šatorom i dok mu se njezin dolazak najavljivao.',
        19: 'Divljahu se ljepoti njezinoj i sinovima Izraelovim zbog nje. I govorahu jedan drugome: "Tko može prezreti narod koji ima takve žene? Zacijelo ne bi valjalo ostaviti u životu i jednog čovjeka toga naroda. Kad bi ga ostavili na miru, bili bi kadri opčiniti sav svijet."',
        20: 'Holofernove straže i dvorjanici njegovi iziđoše i uvedoše Juditu u šator.',
        21: 'Holoferno je počivao na ležaljci za zastorom od grimiza, zlata, smaragda i dragoga kamenja.',
        22: 'Izvijestiše ga o dolasku njezinu i on iziđe na šatorski ulaz: pred njim su nosili srebrne svjetiljke uljanice.',
        23: 'Kad se Judita nađe pred njim i njegovim dvorjanicima, svi se zadiviše ljupkosti lica njezina. Ona se pokloni padnuvši ničice. Sluge je Holofernove podigoše.',
    },
    11: {
        1: 'Kaza joj tada Holoferno: "Budi hrabra, ženo! Ne plaši se u srcu svome! Jer nisam nanio zla nikome od onih koji odlučiše služiti Nabukodonozora, kralja sve zemlje.',
        2: 'Pa da me i tvoj narod koji živi u brdovitu kraju nije prezreo, ja ne bih digao koplja na nj. Ali su sami to skrivili.',
        3: 'Nego, sada mi reci zašto si pobjegla od njih a došla k nama. Došla si da se spasiš! Hrabro, život će ti biti pošteđen noćas a i poslije.',
        4: 'Nitko ti neće nanijeti zla, nego će se postupati s tobom kako se postupa sa slugama moga gospodara i kralja Nabukodonozora."',
        5: 'Judita mu odgovori: "Poslušaj riječi robinje svoje. Neka sluškinji tvojoj bude dopušteno govoriti s tobom: neću noćas govoriti laži svome gospodaru.',
        6: 'Budeš li slijedio savjete sluškinje svoje, Bog će ti pomoći sretno izvesti djelo tvoje, a gospodar moj neće biti razočaran sa svojih pothvata.',
        7: 'Neka živi Nabukodonozor, kralj sve zemlje, neka živi moć onoga koji te uputio kako bi uzmogao na pravi put izvesti svako živo biće! Pomoću tebe nisu mu doista podvrgnuti samo ljudi nego, zahvaljujući vrijednosti tvojoj, i divlje i domaće životinje i ptice nebeske: sve živi samo za Nabukodonozora i svu kuću njegovu.',
        8: 'Dočuli smo već i za razboritost i za oštroumnost tvoju. Svoj je zemlji znano da si u svem kraljevstvu samo ti sposoban, vrstan i pronicav u ratnom umijeću.',
        9: 'Doznali smo i za govor što ga je Ahior izgovorio na tvome vijećanju; budući da su ga stanovnici Betulije spasili, on im je kazao sve što je rekao pred tobom.',
        10: 'A sada, moćni gospodaru, nemoj potcjenjivati njegovo razlaganje nego ga pohrani u srcu svome jer je istinito: ne može se rod naš progoniti niti ga može dohvatiti mač, osim ako sagriješi Bogu svome.',
        11: 'Ali da moj gospodar ne bi ostao razočaran i promašio u svome pothvatu, past će na glavu njihovu smrt: tereti ih grijeh kojim su razgnjevili Boga svoga počinivši bezakonje.',
        12: 'Kako im je ponestalo hrane, a i vode imaju sve manje, prohtjelo im se da navale na stoku svoju i odlučiše da jedu što im je Bog zakonima zabranio.',
        13: 'Čak su naumili potrošiti prvine žita i desetine vina i ulja, čuvane i namijenjene svećenicima koji u Jeruzalemu služe Boga našega; a ipak su to stvari kojih se nitko od naroda nije smio ni rukom dodirnuti.',
        14: 'Otpravili su u Jeruzalem, budući da i tamošnji stanovnici isto rade, glasnike da im donesu potrebno dopuštenje od Vijeća starješina.',
        15: 'Čim im stigne dopuštenje te izvrše svoj naum, toga istog dana bit će ti predani na uništenje.',
        16: 'Kada sam ja, sluškinja tvoja, doznala sve to, pobjegoh od njih. Bog me poslao da sudjelujem s tobom u pothvatu kojemu će se začuditi sva zemlja kada za nj čuje.',
        17: 'Jer sluškinja je tvoja pobožna i štuje Boga nebeskoga i dan i noć, pa sada, kad ostanem uza te, gospodaru, tvoja će sluškinja samo zatražiti da može noću otići prema dolini. Ondje ću moliti Boga, pa će mi kazati kada oni počine grijeh.',
        18: 'Zatim ću se vratiti i tebe obavijestiti, i ti ćeš tada izaći sa svom vojskom. Među njima neće biti nikoga da ti se odupre.',
        19: 'Odvest ću te kroz Judeju sve do samog Jeruzalema, postavit ću usred njega prijestolje tvoje. Ti ćeš ih tjerati pred sobom kao što se tjera stado koje nema pastira. Ni pas pred tobom neće zalajati. Sve sam to predosjetila, to mi je objavljeno, pa sam poslana da ti odam."',
        20: 'Te se riječi svidješe Holofernu i svima njegovim slugama. Zadiviše se mudrosti njezinoj te uzviknuše:',
        21: '"Od jednoga do drugog kraja svijeta nema ravne njoj ljepotom lika i mudrošću razlaganja."',
        22: 'A Holoferno joj reče: "Dobro je učinio Bog što te poslao pred tvojim narodom da nama pripadne moć, a propast onima koji su prezreli moga gospodara.',
        23: 'A ti si plemenita izgledom i lijepo zboriš. Budeš li sve učinila kao što si kazala, tvoj Bog postat će i moj Bog, a ti ćeš provoditi svoje dane u palači kralja Nabukodonozora i bit ćeš slavna na svoj zemlji."',
    },
    12: {
        1: 'Zapovjedi da je odvedu na mjesto gdje je bilo pohranjeno srebrno posuđe i naredi da joj daju od jela njegovih i od vina njegova.',
        2: 'Ali Judita odgovori: "Neću toga jesti da ne bude sablazni, nego neka mi se jelo priređuje od onoga što sam donijela sa sobom."',
        3: 'Holoferno je zapita: "Kad ti ponestane što imaš uza se, odakle ćemo ti davati takva jela kad među nama nema nikoga od tvoga roda?"',
        4: 'Judita odgovori: "Života mi tvoga, gospodaru, ropkinja tvoja neće ni utrošiti što je sa sobom donijela, a Gospod će već rukom njezinom izvesti što je odlučio."',
        5: 'Onda je sluge Holofernove odvedoše u šator. Spavala je do ponoći. Ustade o jutarnjoj straži.',
        6: 'Poruči Holofernu: "Neka gospodar moj dopusti da sluškinja njegova iziđe radi molitve."',
        7: 'Holoferno naredi svojim stražarima da je u tome ne ometaju. Ostala je tako tri dana u taboru. Noću je išla u dolinu Betulije i umivala se na studencu u taboru.',
        8: 'Kad bi tako izišla, molila bi Gospoda, Boga Izraelova, da joj korake upravi na slavu sinova naroda njezina.',
        9: 'Vrativši se čista, zadržala bi se u šatoru dok joj ne bi navečer priredili jelo.',
        10: 'Četvrtoga dana Holoferno priredi gozbu samo za svoje časnike. Ne pozva nikoga od posluge.',
        11: 'Reče dvoraninu Bagoi, upravitelju svih svojih dobara: "Idi i nagovori onu Hebrejku koja je kod tebe da dođe jesti i piti s nama.',
        12: 'Bila bi nam prava sramota imati uza se takvu ženu a ne biti s njom; jer ako je ne predobijemo, rugat će nam se."',
        13: 'Bagoa izađe od Holoferna, uđe k njoj i reče joj: "Neka ljepojka ne oklijeva doći k mome gospodaru da bude čašćena u njegovoj nazočnosti, da veselo pije vino s nama i postane ovoga dana kao jedna od asirskih kćeri koje žive u dvoru Nabukodonozorovu."',
        14: 'Judita mu odgovori: "Tko sam ja da se usprotivim svome gospodaru? Učinit ću smjesta sve što je drago oku njegovu. Bit će mi to radost sve do smrti."',
        15: 'Ustade, ukrasi se haljinama i svakakvim ženskim uresima. Sluškinja ode prije nje te prostrije po zemlji pred Holoferna ovnujske kože koje je dobila od Bagoe za svakidašnju upotrebu da na njima svakoga dana udobno blaguje.',
        16: 'Judita uđe i smjesti se. Holofernu se srce uzbudi, duša mu se uznemiri i spopade ga ognjena žudnja da bude s njom. Od onoga dana kad ju je prvi put vidio, samo je vrebao priliku da je zavede.',
        17: 'Kaza joj Holoferno: "DÓe pij i veseli se s nama!"',
        18: 'Judita odgovori: "Hoću, pit ću, gospodaru, jer osjećam da je danas moj život tako velik kako nije bio nikada od moga rođenja."',
        19: 'Uzela je, jela je i pila pred njim što joj njezina sluškinja bijaše priredila.',
        20: 'Holoferno je uživao u njoj i pio je toliko vina koliko ga nije pio nikad u životu.',
    },
    13: {
        1: 'A uvečer se časnici brzo povukoše. Bagoa zatvori šator izvana, pošto je otpravio od svoga gospodara one koji su se još ondje nalazili. Svi odoše na počinak: bijahu umorni jer se gozba jako oduljila.',
        2: 'Juditu ostaviše samu u šatoru. Holoferno pao na postelju jer ga vino bijaše potpuno svladalo.',
        3: 'Judita je naredila svojoj sluškinji da je čeka pred ložnicom kao i svakog dana. Rekla je da će izaći na molitvu. Tako je kazala i Bagoi.',
        4: 'Svi bijahu otišli od Holoferna, nitko, ni malen ni velik, nije ostao u ložnici. Judita, stojeći kraj Holofernove postelje, reče u srcu svom: "Gospode, Bože svake sile, svrni u ovome času pogled svoj na djelo ruku mojih da se prodiči Jeruzalem!',
        5: 'Ovo je pravi čas da se pobrineš za svoju baštinu i ostvariš moju zamisao o propasti neprijatelja koji su nasrnuli na nas."',
        6: 'Priđe stupu postelje, do Holofernove glave, i skide odande Holofernov mač.',
        7: 'Zatim, primaknuvši se postelji, zgrabi kosu Holofernovu i kaza: "Gospodine Bože Izraelov, ojačaj me danas!"',
        8: 'I iz sve snage udari dvaput Holoferna po vratu i odrubi mu glavu.',
        9: 'Njegov trup potom otkotrlja s ležaja i strže zastor sa stupova. Malo kasnije iziđe i glavu Holofernovu predade sluškinji.',
        10: 'Ona je metnu u svoju torbu. Obadvije zatim, po običaju, iziđoše na molitvu. Prešavši tabor, zaokružiše ono podolje, popeše se na uzvisinu Betulije i dođoše pod njezina vrata.',
        11: 'Judita se javi još izdaleka straži na vratima: "Otvorite, otvorite vrata! S nama je Bog naš da izvede junaštvo u Izraelu i jakost protiv neprijatelja kao što je učinio i danas."',
        12: 'Kako građani začuše njezin glas, požuriše se do vrata svoga grada i pozvaše starješine gradske.',
        13: 'Strčaše se svi, malo i veliko, jer ih je njezin dolazak iznenadio. Otvoriše vrata, primiše ih, zapališe vatru da se vide i okružiše ih.',
        14: 'Judita im jakim glasom kaza: "Hvalite Boga! Hvalite ga! Hvalite Boga koji nije uskratio milosti svoje kući Izraelovoj nego je mojom rukom noćas potukao neprijatelje naše."',
        15: 'Izvadivši glavu iz torbe, pokaza im je i reče: "Evo glave Holoferna, vrhovnog zapovjednika vojske asirske, i evo zastora pod kojim je ležao pijan. Bog ga je pogodio rukom jedne žene!',
        16: 'Neka živi Gospodin koji me zaštitio na putu kojim sam hodila! Jer je moje lice zatravilo Holoferna na propast njegovu, nije zgriješio sa mnom te me tako nije osramotio ni okaljao."',
        17: 'Puk, sav izvan sebe, pade ničice da se pokloni Bogu i povika u jedan glas: "Blagoslovljen da si, Bože naš, koji si danas satro neprijatelje naroda svoga!"',
        18: 'Ozija joj kaza: "Blagoslovljena bila, kćeri, od Boga Svevišnjega više od svih drugih žena na zemlji! Blagoslovljen Gospod Bog, stvoritelj neba i zemlje, koji te vodio da odsiječeš glavu vođi neprijatelja naših!',
        19: 'Jer tvoje pouzdanje neće biti izbrisano iz srdaca ljudi nego će se oni dovijeka sjećati Božje moći.',
        20: 'Neka Bog učini da to bude na tvoju vječnu diku i neka te nagradi svakim dobrom, jer kad bi ponižen naš rod, nisi štedjela života svoga, nego si spriječila našu propast živeći pravedno pred našim Bogom!" A sav narod nadoda: "Amen! Amen!"',
    },
    14: {
        1: 'Judita im reče: "Poslušajte me, braćo! Uzmite ovu glavu i objesite je na krunište naših zidina.',
        2: 'Čim zora zarudi te sunce obasja zemlju, neka se svatko maši svog oružja i svi hrabri muževi neka izađu iz grada. Izabrat ćete im vođu kao da tobože hoćete sići u ravnicu, na asirske predstraže. Ali nećete sići.',
        3: 'Oni će pograbiti svoje oružje, otići će u tabor i probudit će zapovjednike asirske vojske. Zajedno će otrčati k Holofernovu šatoru, i kad Holoferna ne nađu, spopast će ih užas i pobjeći će ispred vas.',
        4: 'Vi i svi koji žive u granicama Izraela, progonite ih i uništite na putu njihova uzmaka.',
        5: 'Ali prije nego sve to izvedete, pozovite mi Ahiora Amonca da svojim očima prepozna onoga koji je prezreo kuću Izraelovu a njega poslao k nama u smrt."',
        6: 'Pozvaše Ahiora iz Ozijine kuće. Kako dođe i vidje Holofernovu glavu u rukama jednog od članova narodnoga zbora, sruši se na zemlju i onesvijesti.',
        7: 'Kada se osvijestio, baci se do nogu Juditi, pokloni joj se i uskliknu: "Blagoslovljena da si u svakome šatoru Judinu i u svakom narodu! Svatko će drhtati od straha kad čuje tvoje ime!',
        8: 'A sada mi pripovjedi što si sve izvela ovih dana." Judita mu usred mnoštva pripovjedi sve što je učinila od onoga dana kad je otišla pa do tada, do toga razgovora s njima.',
        9: 'Kad je završila kazivanje, narod počne klicati od radosti: svim gradom odjeknuše radosni povici.',
        10: 'Tada Ahior, vidjevši što je sve učinio Bog Izraelov, povjerova čvrsto u Boga te se dade obrezati i tako bi pribrojen narodu Izraelovu.',
        11: 'A kad zarudje zora, objesiše Holofernovu glavu na zidine. Svaki pograbi svoje oružje te jurnuše u odredima niz padine.',
        12: 'Kada ih Asirci ugledaše, obavijestiše svoje zapovjednike. Ovi pođoše zapovjednicima, tisućnicima i ostalim časnicima svojim.',
        13: 'Dođoše do Holofernova šatora pa kazaše upravitelju njegovih dobara: "DÓe probudi našega gospodara. Oni su se robovi usudili sići i napasti nas da zauvijek budu uništeni."',
        14: 'Bagoa uđe i pljesnu rukama pred šatorskim zastorom: mišljaše da Holoferno spava s Juditom.',
        15: 'Ali kako se nitko ne odazva, razmaknu zastore, uđe u ložnicu i nađe truplo bačeno na prag: glave nigdje, bijaše odnesena.',
        16: 'Kriknu iza glasa te plačući, jecajući i snažno zapomažući rastrga na sebi haljine.',
        17: 'Uđe zatim u šator u kojem je boravila Judita i ne nađe je. Onda otrča k narodu i povika:',
        18: '"Ovi su robovi podmukli: jedna sama Hebrejka osramotila je dom kralja Nabukodonozora. Evo Holoferna na zemlji, ali glave na njemu nema."',
        19: 'Kad zapovjednici vojske asirske čuše te riječi, razderaše na sebi haljine, dušu im spopade silan strah, a taborom im se prolomiše oštri krikovi i silna kuknjava.',
    },
    15: {
        1: 'I oni koji su se još nalazili u šatorima, kad su čuli što se dogodilo, skameniše se.',
        2: 'Uhvati ih strava i strah te ne bijaše čovjeka koji bi ostao uza svoga bližnjega, nego se svi bezglavo razbježaše po svim brdima i ravnicama.',
        3: 'I oni koji se bijahu utaborili u brdovitom kraju oko Betulije nagoše u bijeg. Tada se Izraelci sa svim svojim ratnicima baciše na njih.',
        4: 'Ozija posla u Betomastaim, Bebe, Kobe, Kolu i na sve područje Izraela skoroteče s porukom o onome što se dogodilo: neka svi nasrnu na neprijatelje te ih unište.',
        5: 'Čim to doznaše, svi sinovi Izraelovi jednodušno udariše na njih te su ih tukli sve do Hobe. Tako učiniše i oni koji su pristigli iz Jeruzalema i sa svih brda, jer je i njima javljeno što se dogodilo u neprijateljskom taboru. Žitelji Gileada i Galileje udariše zatim s boka te su ih žestoko tukli sve dok ne umakoše u Damask i njegove krajeve.',
        6: 'Ostali stanovnici Betulije nasrnuše na tabor Asiraca, oboriše ga te nagrabiše bogat plijen.',
        7: 'Vrativši se s pokolja, sinovi Izraelovi zagospodariše preostalim. I sela i gradići po brdima i ravnicama domogoše se silna plijena; bijaše ga doista mnogo.',
        8: 'Veliki svećenik Joakim i starješine sinova Izraelovih koji su živjeli u Jeruzalemu dođoše da se dive dobročinstvu što ga Gospod učini Izraelu, da vide Juditu i da je pozdrave.',
        9: 'Kad uđoše u kuću njezinu, svi je jednodušno blagosloviše govoreći: "Ti si slava Jeruzalema! Ti si najviši ponos Izraela! Ti si uzvišena dika roda našega!',
        10: 'Rukom svojom sve si to učinila, Izraelu dobra pribavila, Bogu samom time omiljela! Blagoslovljena da si na vječna vremena od Gospoda Svevladara." A sav narod reče: "Amen!"',
        11: 'Trideset je dana narod pljačkao tabor. Juditi dadoše šator Holofernov, svu srebrninu, naslonjače, posuđe i sav njegov namještaj. Ona uze sve to, natovari svoju mazgu, zatim dade upregnuti svoja kola te ih napuni.',
        12: 'Sve su žene Izraelove trčale da je vide, hvalile je i plesove izvodile u čast njezinu. Onda ona uze bršljane u ruke i pokloni ih ženama koje su je pratile.',
        13: 'Zatim se ona i njezine pratilice ovjenčaše maslinovim grančicama. Ona je stupala na čelu naroda i predvodila žene u plesu; slijedili su je Izraelci naoružani, okićeni vijencima i s hvalospjevom na usnama.',
        14: 'Usred sveg Izraela Judita zapjeva ovu zahvalnicu, a sav je narod glasno prihvatio taj hvalospjev.',
    },
    16: {
        1: 'Judita zapjeva: "Slavite Boga moga s bubnjevima, Gospodinu pjevajte s cimbalima, psalam i pohvalu izvijajte mu u čast, veličajte i zazivajte Ime njegovo!',
        2: 'Jer Gospod Bog što dokončava ratove, da bi udario tabor svoj usred naroda, izbavi me iz ruke progonitelja mojih.',
        3: 'Asur siđe s planina sjevernih, dođe sa silnom vojskom svojom. Mnoštvo njihovo potoke zakrči, konji njihovi bregove prekriše.',
        4: 'Kaza da će kraj moj zapaliti, moje mladiće mačem isjeći, o tlo razmrskati moju dojenčad, kao plijen moju djecu uzeti, ugrabiti moje djevice.',
        5: 'Gospod Svevladar svlada ih rukom žene jedne!',
        6: 'Nisu im mladići silnika slomili, Titanovi sinovi nisu ga oborili, divovi silni nisu ga napali, nego Judita, kći Merarijeva, ljepotom svoga lica njega uništi!',
        7: 'Ona svuče udovičke haljine, da bi Izraelce ugnjetene podigla, namaza lice mašću mirisnom,',
        8: 'na kose prevjes stavi, lanene halje uze da ga opčini.',
        9: 'Sandala njemu oko zatravi, ljepota njena dušu mu zarobi, mač mu kroza šiju prođe.',
        10: 'Perzijce njena hrabrost osupnu, a Medijce smionost zaprepasti.',
        11: 'Tad viknuše ponizni moji, a oni se prepadoše, nemoćni moji, a oni se prestraviše; podigoše glas, a oni u bijeg nagoše!',
        12: 'Djevojčica sasjekoše ih sinovi, pobiše ih kao sinove odmetnika, u boju Boga moga pogiboše.',
        13: 'Bogu svom pjevat ću pjesmu novu. Velik si i slavan, Gospode! U sili divan i nepobjediv!',
        14: 'Sva stvorenja tvoja tebi neka služe, jer ti samo reče, i postadoše; posla duh svoj, i on ih oblikova. I glasu tvome nitko ne odolje.',
        15: 'Planine će se iz temelja s vodama potresti, hridi će se pred tobom kao od voska istopiti, ali prema onima koji te se boje ti ćeš i tada milostiv biti.',
        16: 'Neznatna ti je svaka žrtva na ugodan miris, još neznatnija pretilina paljenice, ali tko se boji Gospoda - velik je zauvijek.',
        17: 'Jao narodima koji ustanu na narod moj! Bog Svevladar kaznit će ih na dan Suda: poslat će oganj i crve u meso njihovo, a oni će u boli jaukati zauvijek."',
        18: 'Kada dođoše u Jeruzalem, pokloniše se Bogu, a pošto se narod očisti, prinesoše paljenice, dragovoljne prinose i darove.',
        19: 'Judita posveti kao "herem" sve Holofernove predmete koje joj puk bijaše predao i svilene tkanine koje bijaše uzela s postelje njegove.',
        20: 'Narod se veselio tri mjeseca u Jeruzalemu pred Svetištem i Judita je ostala s njima.',
        21: 'A nakon tih dana svaki se vrati na svoju baštinu. Judita se povuče u Betuliju i osta na svom posjedu. I svega vijeka svojega bila je slavna na svoj zemlji.',
        22: 'Mnogi su je prosili, ali ona ne upozna ni jednoga čovjeka u sve dane života svojega otkad joj umrije muž Manaše i bi pridružen narodu svome.',
        23: 'Starjela je i u domu muža svojega postigla dob od sto i pet godina. Sluškinji svojoj dala je slobodu. Umrije u Betuliji. Pokopaše je u pećini Manašea, muža njezina.',
        24: 'Dom Izraelov oplakivaše je sedam dana. Prije smrti razdijelila je svoja dobra rođacima svojim i rođacima muža svojega Manašea.',
        25: 'U Juditino vrijeme, a i mnogo poslije smrti njezine, ne bijaše nikoga tko bi zadavao strah sinovima Izraelovim.',
    },
}
